    'tools.legal.privacy.s1Title': '1. Data we collect',
    'tools.legal.privacy.s1Body': 'At Naje AI we respect your privacy. When you register we collect basic data such as your email, username, and profile photo. Conversation text and prompts are also collected to improve the experience and deliver AI outputs.',
    'tools.legal.privacy.s2Title': '2. How we use your data',
    'tools.legal.privacy.s2Body': 'Your data is used to manage your account and to provide content-generation services. We may use operational data to analyze platform performance and improve our models. We do not sell your personal data to any third party.',
    'tools.legal.privacy.s3Title': '3. Third parties',
    'tools.legal.privacy.s3Body': 'We rely on trusted providers (such as Google Cloud and Firebase) to host data, authenticate users, and supply core AI model services. Data shared with these parties is subject to their own privacy policies.',
    'tools.legal.privacy.s4Title': '4. Data security',
    'tools.legal.privacy.s4Body': 'We apply strict security measures and advanced encryption to protect your data from unauthorized access, alteration, or destruction. However, no transmission over the internet is 100% secure.',
    'tools.legal.privacy.s5Title': '5. Your rights and data deletion',
    'tools.legal.privacy.s5Body': 'You have the full right to request access to your personal data, to correct it, or to request permanent deletion of your account and all associated data from our servers and databases.',
    'tools.legal.privacy.deleteBoxTitle': 'Account and data deletion request link:',
    'tools.legal.privacy.deleteBoxDesc': 'You can submit an immediate request to delete your account and permanently destroy your data via the dedicated link:',
    'tools.legal.privacy.deleteBtn': 'Account deletion request page',
    'tools.legal.privacy.s6Title': '6. Administrative access to content',
    'tools.legal.privacy.s6Intro': 'Authorized members of the Naje AI team (“authorized staff”) may review conversation content and materials linked to a user account, solely for the following purposes:',
    'tools.legal.privacy.s6i1': 'Providing technical support when the user expressly asks for help with a specific conversation or generation result.',
    'tools.legal.privacy.s6i2': 'Reviewing reports of acceptable-use violations or misuse of the platform.',
    'tools.legal.privacy.s6i3': 'Diagnosing technical failures and ensuring service quality.',
    'tools.legal.privacy.s6i4': 'Complying with any applicable legal obligation.',
    'tools.legal.privacy.s6Foot': 'This access is limited to authorized staff within the scope of their duties. Content is not used for marketing and is not shared with any third party beyond what this policy states. Naje AI keeps an internal log of administrative access to conversations for accountability.',
    'tools.legal.terms.s1Title': '1. Introduction',
    'tools.legal.terms.s1Body': 'Welcome to NAJE Studio (Naje AI). By using our platform and application, you expressly agree to comply with these terms and conditions. If you do not agree with any part of these terms, please refrain from using our services.',
    'tools.legal.terms.s2Title': '2. Use of the services',
    'tools.legal.terms.s2Body': 'Naje AI gives you access to AI-based tools for creating text, visual, and administrative content. These services must be used only for lawful and legitimate purposes. Using the platform to generate abusive or illegal content, or content that infringes others’ intellectual-property rights, is prohibited.',
    'tools.legal.terms.s3Title': '3. Accounts and security',
    'tools.legal.terms.s3Body': 'You are fully responsible for keeping your account information confidential and for any activity under it. We reserve the right to suspend or terminate accounts that violate the terms of service or misuse the system.',
    'tools.legal.terms.s4Title': '4. Intellectual property',
    'tools.legal.terms.s4Body': 'All copyrights, trademarks, and intellectual property associated with the Naje AI platform (including design and software) belong to Naje AI. Content you generate through the platform belongs to you under the licenses of the models used, and Naje AI accepts no legal liability for how you use it.',
    'tools.legal.terms.s5Title': '5. Changes to the service',
    'tools.legal.terms.s5Body': 'We reserve the right to modify, suspend, or discontinue the service (or any part of it) at any time without prior notice. We may also update these terms, and your continued use of the service constitutes acceptance of the revised terms.',
    'tools.legal.terms.s6Title': '6. Limitation of liability',
    'tools.legal.terms.s6Body': 'Under no circumstances shall Naje AI be liable for any direct or indirect damages arising from the use of, or inability to use, the services provided.',
    'tools.delete.toastCopied': 'Account deletion request link copied.',
    'tools.delete.toastCopyFail': 'Could not copy the link.',
    'tools.delete.toastBadEmail': 'Please enter a valid email address.',
    'tools.delete.toastNeedConfirm': 'Please confirm that you accept permanent account deletion.',
    'tools.delete.toastReceived': 'Account deletion request received.',
    'tools.delete.reasonUnspecified': 'No reason provided',
    'tools.delete.emailSubject': 'Account Deletion Request - NAJE Studio',
    'tools.delete.brand': 'NAJE Studio AI',
    'tools.delete.mySettings': 'My Settings',
    'tools.delete.signIn': 'Sign In',
    'tools.delete.pageTitle': 'Account & Data Deletion Request',
    'tools.delete.pageDesc': 'Official guide and procedure for permanently deleting your account and all associated data in compliance with global privacy policies and app store requirements.',
    'tools.delete.officialUrlLabel': 'Official Account Deletion Request URL:',
    'tools.delete.copyUrl': 'Copy URL',
    'tools.delete.copied': 'Copied',
    'tools.delete.loggedInAs': 'You are currently logged in as:',
    'tools.delete.instantDeleteNotice': 'You can delete your account and data immediately in one click from the Settings page.',
    'tools.delete.instantDeleteBtn': 'Instant Deletion from Settings',
    'tools.delete.whatDataTitle': 'What data is deleted upon request execution?',
    'tools.delete.whatDataDesc': 'Upon confirmation of account deletion, our systems permanently purge all associated records with no possibility of recovery:',
    'tools.delete.itemProfile': 'Profile Information: Full name, email address, profile picture, and app preferences.',
    'tools.delete.itemProjects': 'Workspaces & Projects: All created, uploaded, or generated files and documents.',
    'tools.delete.itemChats': 'AI & Chat History: Messages, audio transcripts, source code, and AI memory.',
    'tools.delete.itemBalance': 'Credits & Balance: Any remaining points or tokens are permanently forfeited.',
    'tools.delete.itemMedia': 'Media & Gallery: Generated images, motion clips, and video productions.',
    'tools.delete.retentionNotice': 'Data Retention: No personal identifiers are retained after deletion. Only anonymized transaction logs required by mandatory financial regulations are kept for up to 30 days.',
    'tools.delete.formTitle': 'Submit Online Deletion Request Directly',
    'tools.delete.formDesc': 'Fill out the form below to submit an official request to delete your account and data. Requests are processed within 24 to 48 hours.',
    'tools.delete.successTitle': 'Account Deletion Request Received Successfully',
    'tools.delete.refNumber': 'Reference ID:',
    'tools.delete.successDesc': 'Our technical support team will process the deletion and permanently erase all records associated with this email address within 48 hours.',
    'tools.delete.emailLabel': 'Account Email to Delete',
