    'tools.delete.reasonPlaceholder': 'Help us improve by sharing why you wish to delete your account...',
    'tools.delete.confirmNotice': 'I understand and agree that deleting my account will permanently delete all projects, chats, files, and credit balance with no possibility of recovery.',
    'tools.delete.submitting': 'Submitting request...',
    'tools.delete.submitBtn': 'Submit Account Deletion Request',
    'tools.delete.altMethodsTitle': 'Alternative Methods for Deletion',
    'tools.delete.altAppTitle': 'Instant Deletion from App',
    'tools.delete.altAppDesc': 'Sign in, navigate to Settings, and click "Delete My Account Permanently" at the bottom for instant automated execution.',
    'tools.delete.goToSettings': 'Go to Settings',
    'tools.delete.altEmailTitle': 'Email Request to Support',
    'tools.delete.altEmailDesc': 'Send an email titled "Account Deletion Request - NAJE Studio" to our support team:',
