    'tools.delete.copyright': 'NAJE Studio AI & Qelva Ai © All rights reserved',
    'tools.agent.greeting': 'Welcome! I am Naje Agent — a multi-agent system for brand identity, ad copy, and end-to-end project engineering. Upload your files and sources in the Sources tab so the identity and advertising agents can use them while building your project. Describe your idea and we will plan and execute step by step.',
