    'tools.authAction.saveNewPassword': 'Guardar nueva contraseña',
    'tools.sitemap.subtitle': 'Acceso rápido a todas las secciones de NAJE Studio',
    'tools.sitemap.publicPages': 'Páginas públicas',
    'tools.sitemap.platform': 'Estudios de la plataforma',
    'tools.favorites.exportPdfError': 'Error al exportar el PDF',
    'tools.favorites.savedFavorite': 'Favorito guardado',
    'tools.favorites.general': 'General',
    'tools.legal.privacy.s1Title': '1. Datos que recopilamos',
    'tools.legal.privacy.s1Body': 'En Naje AI respetamos su privacidad. Al registrarse recopilamos datos básicos como el correo, el nombre de usuario y la foto de perfil. También recopilamos el texto de las conversaciones y las indicaciones (prompts) para mejorar la experiencia y ofrecer resultados de inteligencia artificial.',
    'tools.legal.privacy.s2Title': '2. Cómo usamos sus datos',
    'tools.legal.privacy.s2Body': 'Sus datos se usan para administrar su cuenta y prestar servicios de generación de contenido. Podemos usar datos operativos para analizar el rendimiento de la plataforma y mejorar nuestros modelos. No vendemos sus datos personales a terceros.',
    'tools.legal.privacy.s3Title': '3. Terceros',
    'tools.legal.privacy.s3Body': 'Dependemos de proveedores de confianza (como Google Cloud y Firebase) para alojar datos, autenticar usuarios y ofrecer los servicios básicos de modelos de IA. El intercambio de datos con estas partes se rige por sus propias políticas de privacidad.',
    'tools.legal.privacy.s4Title': '4. Seguridad de los datos',
    'tools.legal.privacy.s4Body': 'Aplicamos medidas de seguridad estrictas y cifrado avanzado para proteger sus datos frente al acceso no autorizado, la alteración o la destrucción. Ninguna transmisión por internet es segura al 100%.',
    'tools.legal.privacy.s5Title': '5. Sus derechos y la eliminación de datos',
    'tools.legal.privacy.s5Body': 'Tiene pleno derecho a solicitar acceso a sus datos personales, a corregirlos o a pedir la eliminación permanente de su cuenta y de todos los datos asociados de nuestros servidores y bases de datos.',
    'tools.legal.privacy.deleteBoxTitle': 'Enlace de solicitud de eliminación de cuenta y datos:',
    'tools.legal.privacy.deleteBoxDesc': 'Puede presentar de inmediato una solicitud para eliminar la cuenta y destruir sus datos de forma permanente en el enlace dedicado:',
    'tools.legal.privacy.deleteBtn': 'Página de solicitud de eliminación de cuenta',
    'tools.legal.privacy.s6Title': '6. Acceso administrativo al contenido',
    'tools.legal.privacy.s6Intro': 'Personas autorizadas del equipo de Naje AI («personal autorizado») pueden revisar el contenido de las conversaciones y los materiales vinculados a la cuenta del usuario, exclusivamente para los fines siguientes:',
    'tools.legal.privacy.s6i1': 'Prestar soporte técnico cuando el usuario solicite expresamente ayuda sobre una conversación o un resultado de generación concreto.',
    'tools.legal.privacy.s6i2': 'Verificar denuncias de incumplimiento de la política de uso o de abuso de la plataforma.',
    'tools.legal.privacy.s6i3': 'Diagnosticar fallos técnicos y garantizar la calidad del servicio.',
    'tools.legal.privacy.s6i4': 'Cumplir cualquier obligación legal vigente.',
    'tools.legal.privacy.s6Foot': 'Este acceso se limita al personal autorizado en el ámbito de sus funciones. El contenido no se usa con fines de marketing ni se comparte con terceros fuera de lo previsto en esta política. Naje AI conserva un registro interno de los accesos administrativos a las conversaciones con fines de rendición de cuentas.',
    'tools.legal.terms.s1Title': '1. Introducción',
    'tools.legal.terms.s1Body': 'Bienvenido a NAJE Studio (Naje AI). Al usar nuestra plataforma y aplicación, acepta expresamente cumplir estos términos y condiciones. Si no está de acuerdo con alguna parte, absténgase de usar nuestros servicios.',
    'tools.legal.terms.s2Title': '2. Uso de los servicios',
    'tools.legal.terms.s2Body': 'Naje AI le da acceso a herramientas basadas en IA para crear contenido textual, visual y administrativo. Estos servicios deben usarse solo con fines lícitos y legítimos. Está prohibido usar la plataforma para generar contenido abusivo, ilegal o que infrinja derechos de propiedad intelectual de terceros.',
    'tools.legal.terms.s3Title': '3. Cuentas y seguridad',
    'tools.legal.terms.s3Body': 'Usted es plenamente responsable de mantener la confidencialidad de la información de su cuenta y de cualquier actividad realizada con ella. Nos reservamos el derecho de suspender o cancelar las cuentas que infrinjan las condiciones o abusen del sistema.',
    'tools.legal.terms.s4Title': '4. Propiedad intelectual',
    'tools.legal.terms.s4Body': 'Todos los derechos de autor, marcas y propiedad intelectual asociados a la plataforma Naje AI (incluido el diseño y el software) pertenecen a Naje AI. El contenido que genere a través de la plataforma le pertenece conforme a las licencias de los modelos utilizados, sin que Naje AI asuma responsabilidad legal por el uso que haga de él.',
    'tools.legal.terms.s5Title': '5. Modificaciones del servicio',
    'tools.legal.terms.s5Body': 'Nos reservamos el derecho de modificar, suspender o interrumpir el servicio (o cualquier parte) en cualquier momento y sin aviso previo. También podemos actualizar las condiciones, y el uso continuado del servicio se considerará aceptación de las condiciones modificadas.',
    'tools.legal.terms.s6Title': '6. Limitación de responsabilidad',
