    'tools.favorites.general': 'Général',
    'tools.legal.privacy.s1Title': '1. Données que nous collectons',
    'tools.legal.privacy.s1Body': 'Chez Naje AI, nous respectons votre vie privée. Lors de l’inscription, nous collectons des données de base telles que l’e-mail, le nom d’utilisateur et la photo de profil. Les textes de conversation et les invites (prompts) sont également collectés afin d’améliorer l’expérience et de fournir les résultats d’IA.',
    'tools.legal.privacy.s2Title': '2. Comment nous utilisons vos données',
    'tools.legal.privacy.s2Body': 'Vos données servent à gérer votre compte et à fournir les services de génération de contenu. Nous pouvons utiliser des données opérationnelles pour analyser les performances de la plateforme et améliorer nos modèles. Nous ne vendons pas vos données personnelles à des tiers.',
    'tools.legal.privacy.s3Title': '3. Tiers',
    'tools.legal.privacy.s3Body': 'Nous nous appuyons sur des prestataires de confiance (tels que Google Cloud et Firebase) pour héberger les données, authentifier les utilisateurs et fournir les services de modèles d’IA. Le partage avec ces parties est soumis à leurs propres politiques de confidentialité.',
    'tools.legal.privacy.s4Title': '4. Sécurité des données',
    'tools.legal.privacy.s4Body': 'Nous appliquons des mesures de sécurité strictes et un chiffrement avancé pour protéger vos données contre l’accès non autorisé, la modification ou la destruction. Aucune transmission sur internet n’est sûre à 100 %.',
    'tools.legal.privacy.s5Title': '5. Vos droits et la suppression des données',
    'tools.legal.privacy.s5Body': 'Vous avez pleinement le droit de demander l’accès à vos données personnelles, de les corriger ou de demander la suppression définitive de votre compte et de toutes les données associées de nos serveurs et bases de données.',
    'tools.legal.privacy.deleteBoxTitle': 'Lien de demande de suppression du compte et des données :',
    'tools.legal.privacy.deleteBoxDesc': 'Vous pouvez déposer immédiatement une demande de suppression du compte et de destruction définitive de vos données via le lien dédié :',
    'tools.legal.privacy.deleteBtn': 'Page de demande de suppression de compte',
    'tools.legal.privacy.s6Title': '6. Accès administratif au contenu',
    'tools.legal.privacy.s6Intro': 'Des membres autorisés de l’équipe Naje AI (« personnel autorisé ») peuvent consulter le contenu des conversations et les éléments liés au compte, exclusivement aux fins suivantes :',
    'tools.legal.privacy.s6i1': 'Fournir une assistance technique lorsque l’utilisateur demande expressément de l’aide pour une conversation ou un résultat de génération précis.',
    'tools.legal.privacy.s6i2': 'Vérifier les signalements de violation de la politique d’utilisation ou d’abus de la plateforme.',
    'tools.legal.privacy.s6i3': 'Diagnostiquer les pannes techniques et garantir la qualité du service.',
    'tools.legal.privacy.s6i4': 'Respecter toute obligation légale applicable.',
    'tools.legal.privacy.s6Foot': 'Cet accès est limité au personnel autorisé dans le cadre de ses fonctions. Le contenu n’est pas utilisé à des fins marketing et n’est pas partagé avec un tiers au-delà de ce que prévoit cette politique. Naje AI conserve un journal interne des accès administratifs aux conversations à des fins de responsabilité.',
    'tools.legal.terms.s1Title': '1. Introduction',
    'tools.legal.terms.s1Body': 'Bienvenue sur NAJE Studio (Naje AI). En utilisant notre plateforme et notre application, vous acceptez expressément de respecter les présentes conditions. Si vous n’acceptez pas une partie de ces conditions, veuillez ne pas utiliser nos services.',
    'tools.legal.terms.s2Title': '2. Utilisation des services',
    'tools.legal.terms.s2Body': 'Naje AI vous donne accès à des outils fondés sur l’IA pour créer du contenu textuel, visuel et administratif. Ces services doivent être utilisés uniquement à des fins licites et légitimes. Il est interdit d’utiliser la plateforme pour générer un contenu abusif, illégal ou portant atteinte aux droits de propriété intellectuelle d’autrui.',
    'tools.legal.terms.s3Title': '3. Comptes et sécurité',
    'tools.legal.terms.s3Body': 'Vous êtes entièrement responsable de la confidentialité des informations de votre compte et de toute activité qui s’y déroule. Nous nous réservons le droit de suspendre ou de résilier les comptes qui violent les conditions ou abusent du système.',
    'tools.legal.terms.s4Title': '4. Propriété intellectuelle',
    'tools.legal.terms.s4Body': 'Tous les droits d’auteur, marques et droits de propriété intellectuelle liés à la plateforme Naje AI (y compris le design et le logiciel) appartiennent à Naje AI. Le contenu que vous générez via la plateforme vous appartient selon les licences des modèles utilisés, sans que Naje AI n’assume de responsabilité juridique quant à l’usage que vous en faites.',
    'tools.legal.terms.s5Title': '5. Modifications du service',
    'tools.legal.terms.s5Body': 'Nous nous réservons le droit de modifier, suspendre ou interrompre le service (ou toute partie) à tout moment sans préavis. Nous pouvons aussi mettre à jour les conditions, et la poursuite de l’utilisation vaut acceptation des conditions modifiées.',
    'tools.legal.terms.s6Title': '6. Limitation de responsabilité',
    'tools.legal.terms.s6Body': 'En aucun cas Naje AI ne saurait être responsable de dommages directs ou indirects résultant de l’utilisation ou de l’impossibilité d’utiliser les services fournis.',
