    'tools.legal.privacy.s1Body': 'Bei Naje AI respektieren wir Ihre Privatsphäre. Bei der Registrierung erheben wir grundlegende Daten wie E-Mail, Benutzername und Profilbild. Gesprächstexte und Prompts werden ebenfalls erfasst, um das Erlebnis zu verbessern und KI-Ergebnisse bereitzustellen.',
    'tools.legal.privacy.s2Title': '2. Wie wir Ihre Daten verwenden',
    'tools.legal.privacy.s2Body': 'Ihre Daten dienen der Kontoverwaltung und der Bereitstellung von Inhaltserzeugung. Betriebsdaten können wir zur Analyse der Plattformleistung und zur Weiterentwicklung unserer Modelle nutzen. Wir verkaufen Ihre personenbezogenen Daten nicht an Dritte.',
    'tools.legal.privacy.s3Title': '3. Dritte',
    'tools.legal.privacy.s3Body': 'Wir nutzen vertrauenswürdige Anbieter (etwa Google Cloud und Firebase) zum Hosten von Daten, zur Authentifizierung und für grundlegende KI-Modelldienste. Die Weitergabe an diese Parteien unterliegt deren eigenen Datenschutzrichtlinien.',
    'tools.legal.privacy.s4Title': '4. Datensicherheit',
    'tools.legal.privacy.s4Body': 'Wir setzen strenge Sicherheitsmaßnahmen und moderne Verschlüsselung ein, um Ihre Daten vor unbefugtem Zugriff, Änderung oder Zerstörung zu schützen. Keine Übertragung über das Internet ist zu 100 % sicher.',
    'tools.legal.privacy.s5Title': '5. Ihre Rechte und Datenlöschung',
    'tools.legal.privacy.s5Body': 'Sie haben das volle Recht, Zugang zu Ihren personenbezogenen Daten zu verlangen, sie zu berichtigen oder die dauerhafte Löschung Ihres Kontos und aller zugehörigen Daten von unseren Servern und Datenbanken zu beantragen.',
    'tools.legal.privacy.deleteBoxTitle': 'Link zur Konten- und Datenlöschung:',
    'tools.legal.privacy.deleteBoxDesc': 'Sie können über den vorgesehenen Link sofort die Löschung des Kontos und die endgültige Vernichtung Ihrer Daten beantragen:',
    'tools.legal.privacy.deleteBtn': 'Seite zum Antrag auf Kontolöschung',
    'tools.legal.privacy.s6Title': '6. Administrativer Zugriff auf Inhalte',
    'tools.legal.privacy.s6Intro': 'Befugte Personen des Naje-AI-Teams („befugte Mitarbeitende“) können Gesprächsinhalte und mit dem Konto verbundene Materialien ausschließlich zu folgenden Zwecken einsehen:',
    'tools.legal.privacy.s6i1': 'Technischen Support leisten, wenn der Nutzer ausdrücklich Hilfe zu einem bestimmten Gespräch oder Generierungsergebnis erbittet.',
    'tools.legal.privacy.s6i2': 'Meldungen über Verstöße gegen die Nutzungsrichtlinie oder Missbrauch der Plattform prüfen.',
    'tools.legal.privacy.s6i3': 'Technische Störungen diagnostizieren und die Dienstqualität sichern.',
    'tools.legal.privacy.s6i4': 'Jede geltende gesetzliche Pflicht erfüllen.',
    'tools.legal.privacy.s6Foot': 'Dieser Zugriff ist auf befugte Mitarbeitende im Rahmen ihrer Aufgaben beschränkt. Inhalte werden nicht zu Marketingzwecken verwendet und nicht an Dritte weitergegeben, soweit diese Richtlinie das nicht vorsieht. Naje AI führt ein internes Protokoll der administrativen Zugriffe auf Gespräche zur Rechenschaft.',
    'tools.legal.terms.s1Title': '1. Einleitung',
    'tools.legal.terms.s1Body': 'Willkommen bei NAJE Studio (Naje AI). Durch die Nutzung unserer Plattform und Anwendung stimmen Sie ausdrücklich zu, diese Bedingungen einzuhalten. Wenn Sie einem Teil nicht zustimmen, nutzen Sie unsere Dienste bitte nicht.',
    'tools.legal.terms.s2Title': '2. Nutzung der Dienste',
    'tools.legal.terms.s2Body': 'Naje AI gewährt Ihnen Zugang zu KI-gestützten Werkzeugen zur Erstellung von Text-, Bild- und Verwaltungsinhalten. Diese Dienste dürfen nur für rechtmäßige und legitime Zwecke genutzt werden. Die Erzeugung beleidigender, rechtswidriger oder die geistigen Eigentumsrechte Dritter verletzender Inhalte ist untersagt.',
    'tools.legal.terms.s3Title': '3. Konten und Sicherheit',
    'tools.legal.terms.s3Body': 'Sie sind allein dafür verantwortlich, Ihre Kontodaten vertraulich zu halten und für jede Aktivität unter dem Konto. Wir behalten uns vor, Konten zu sperren oder zu kündigen, die gegen die Nutzungsbedingungen verstoßen oder das System missbrauchen.',
    'tools.legal.terms.s4Title': '4. Geistiges Eigentum',
    'tools.legal.terms.s4Body': 'Alle Urheberrechte, Marken und geistigen Eigentumsrechte an der Naje-AI-Plattform (einschließlich Design und Software) gehören Naje AI. Inhalte, die Sie über die Plattform erzeugen, gehören Ihnen gemäß den Lizenzen der verwendeten Modelle, ohne dass Naje AI für deren Nutzung rechtlich haftet.',
    'tools.legal.terms.s5Title': '5. Änderungen am Dienst',
    'tools.legal.terms.s5Body': 'Wir behalten uns vor, den Dienst (oder Teile davon) jederzeit ohne vorherige Ankündigung zu ändern, auszusetzen oder einzustellen. Wir dürfen die Bedingungen aktualisieren; die weitere Nutzung gilt als Zustimmung zu den geänderten Bedingungen.',
    'tools.legal.terms.s6Title': '6. Haftungsbeschränkung',
    'tools.legal.terms.s6Body': 'Naje AI haftet unter keinen Umständen für unmittelbare oder mittelbare Schäden, die aus der Nutzung oder der Unmöglichkeit der Nutzung der angebotenen Dienste entstehen.',
