    'tools.sitemap.subtitle': 'Acesso rápido a todas as seções do NAJE Studio',
    'tools.sitemap.publicPages': 'Páginas públicas',
    'tools.sitemap.platform': 'Estúdios da plataforma',
    'tools.favorites.exportPdfError': 'Erro ao exportar o PDF',
    'tools.favorites.savedFavorite': 'Favorito salvo',
    'tools.favorites.general': 'Geral',
    'tools.legal.privacy.s1Title': '1. Dados que coletamos',
    'tools.legal.privacy.s1Body': 'Na Naje AI respeitamos a sua privacidade. No registo coletamos dados básicos como e-mail, nome de utilizador e foto de perfil. Também coletamos o texto das conversas e os prompts para melhorar a experiência e entregar os resultados de IA.',
    'tools.legal.privacy.s2Title': '2. Como usamos os seus dados',
    'tools.legal.privacy.s2Body': 'Os seus dados são usados para gerir a conta e fornecer serviços de geração de conteúdo. Podemos usar dados operacionais para analisar o desempenho da plataforma e melhorar os nossos modelos. Não vendemos os seus dados pessoais a terceiros.',
    'tools.legal.privacy.s3Title': '3. Terceiros',
    'tools.legal.privacy.s3Body': 'Recorremos a fornecedores de confiança (como Google Cloud e Firebase) para alojar dados, autenticar utilizadores e fornecer os serviços essenciais de modelos de IA. A partilha com essas partes está sujeita às respetivas políticas de privacidade.',
    'tools.legal.privacy.s4Title': '4. Segurança dos dados',
    'tools.legal.privacy.s4Body': 'Aplicamos medidas de segurança rigorosas e encriptação avançada para proteger os seus dados contra acesso não autorizado, alteração ou destruição. Nenhuma transmissão pela internet é 100% segura.',
    'tools.legal.privacy.s5Title': '5. Os seus direitos e a eliminação de dados',
    'tools.legal.privacy.s5Body': 'Tem o pleno direito de pedir acesso aos seus dados pessoais, de os corrigir ou de solicitar a eliminação permanente da sua conta e de todos os dados associados dos nossos servidores e bases de dados.',
    'tools.legal.privacy.deleteBoxTitle': 'Link do pedido de eliminação da conta e dos dados:',
    'tools.legal.privacy.deleteBoxDesc': 'Pode apresentar de imediato um pedido para eliminar a conta e destruir os seus dados de forma permanente através do link dedicado:',
    'tools.legal.privacy.deleteBtn': 'Página de pedido de eliminação da conta',
    'tools.legal.privacy.s6Title': '6. Acesso administrativo ao conteúdo',
    'tools.legal.privacy.s6Intro': 'Pessoas autorizadas da equipa Naje AI («pessoal autorizado») podem consultar o conteúdo das conversas e os materiais ligados à conta, exclusivamente para os fins seguintes:',
    'tools.legal.privacy.s6i1': 'Prestar suporte técnico quando o utilizador pedir expressamente ajuda sobre uma conversa ou um resultado de geração específico.',
    'tools.legal.privacy.s6i2': 'Verificar denúncias de violação da política de utilização ou de uso indevido da plataforma.',
    'tools.legal.privacy.s6i3': 'Diagnosticar falhas técnicas e garantir a qualidade do serviço.',
    'tools.legal.privacy.s6i4': 'Cumprir qualquer obrigação legal aplicável.',
    'tools.legal.privacy.s6Foot': 'Este acesso limita-se ao pessoal autorizado no âmbito das suas funções. O conteúdo não é usado para marketing nem partilhado com terceiros além do previsto nesta política. A Naje AI mantém um registo interno dos acessos administrativos às conversas para prestação de contas.',
    'tools.legal.terms.s1Title': '1. Introdução',
    'tools.legal.terms.s1Body': 'Bem-vindo ao NAJE Studio (Naje AI). Ao utilizar a nossa plataforma e aplicação, concorda expressamente em cumprir estes termos e condições. Se não concordar com alguma parte, abstenha-se de utilizar os nossos serviços.',
    'tools.legal.terms.s2Title': '2. Utilização dos serviços',
    'tools.legal.terms.s2Body': 'A Naje AI dá-lhe acesso a ferramentas baseadas em IA para criar conteúdo textual, visual e administrativo. Estes serviços devem ser usados apenas para fins lícitos e legítimos. É proibido usar a plataforma para gerar conteúdo abusivo, ilegal ou que viole direitos de propriedade intelectual de terceiros.',
    'tools.legal.terms.s3Title': '3. Contas e segurança',
    'tools.legal.terms.s3Body': 'É inteiramente responsável por manter confidenciais os dados da sua conta e por qualquer atividade nela realizada. Reservamo-nos o direito de suspender ou encerrar contas que violem os termos ou abusem do sistema.',
    'tools.legal.terms.s4Title': '4. Propriedade intelectual',
    'tools.legal.terms.s4Body': 'Todos os direitos de autor, marcas e propriedade intelectual associados à plataforma Naje AI (incluindo o design e o software) pertencem à Naje AI. O conteúdo que gerar através da plataforma pertence-lhe segundo as licenças dos modelos utilizados, sem que a Naje AI assuma responsabilidade legal pela forma como o utiliza.',
    'tools.legal.terms.s5Title': '5. Alterações ao serviço',
    'tools.legal.terms.s5Body': 'Reservamo-nos o direito de modificar, suspender ou descontinuar o serviço (ou qualquer parte) a qualquer momento, sem aviso prévio. Também podemos atualizar os termos, e a continuação do uso constitui aceitação dos termos alterados.',
    'tools.legal.terms.s6Title': '6. Limitação de responsabilidade',
    'tools.legal.terms.s6Body': 'Em nenhuma circunstância a Naje AI será responsável por danos diretos ou indiretos resultantes do uso ou da impossibilidade de usar os serviços prestados.',
